nodes.text_raw:
:root {
  --bg: #0f172a;
  --card: #1e293b;
  --card-2: #273549;
  --accent: #38bdf8;
  --text: #e2e8f0;
  --muted: #94a3b8;
  --line: #334155;
}
* { box-sizing: border-box; margin: 0; padding: 0; }
html, body {
  width: 1280px;
  height: 800px;
  background: linear-gradient(160deg, #0b1120 0%, #0f172a 60%, #1e293b 100%);
  color: var(--text);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  -webkit-font-smoothing: antialiased;
}
body {
  display: flex;
  align-items: center;
  justify-content: center;
}
.card {
  width: 1040px;
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 24px;
  box-shadow: 0 30px 80px rgba(0,0,0,0.45);
  overflow: hidden;
}
.card-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  padding: 36px 44px 28px;
  background: linear-gradient(135deg, #1e293b 0%, #223049 100%);
  border-bottom: 1px solid var(--line);
}
.loc-name {
  font-size: 40px;
  font-weight: 700;
  letter-spacing: -0.5px;
}
.loc-sub {
  margin-top: 6px;
  font-size: 18px;
  color: var(--muted);
}
.loc-coords {
  margin-top: 2px;
  font-size: 14px;
  color: var(--muted);
  font-variant-numeric: tabular-nums;
}
.cond-box {
  text-align: right;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 6px;
}
.cond-icon { font-size: 64px; line-height: 1; }
.cond-text { font-size: 22px; font-weight: 600; }
.body-wrap { padding: 32px 44px 40px; }
.temps {
  display: flex;
  gap: 20px;
  margin-bottom: 34px;
}
.temp-tile {
  flex: 1;
  background: var(--card-2);
  border: 1px solid var(--line);
  border-radius: 16px;
  padding: 22px 26px;
}
.temp-tile .label {
  font-size: 14px;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  color: var(--muted);
}
.temp-tile .val {
  margin-top: 8px;
  font-size: 46px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}
.temp-tile.max .val { color: #fca5a5; }
.temp-tile.min .val { color: #93c5fd; }
.section-title {
  font-size: 16px;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: var(--muted);
  margin-bottom: 16px;
}
.hours {
  display: grid;
  grid-template-columns: repeat(12, 1fr);
  gap: 8px;
}
.hour {
  background: var(--card-2);
  border: 1px solid var(--line);
  border-radius: 10px;
  padding: 12px 4px;
  text-align: center;
}
.hour .h {
  font-size: 12px;
  color: var(--muted);
  font-variant-numeric: tabular-nums;
}
.hour .t {
  margin-top: 8px;
  font-size: 17px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}
.status {
  padding: 60px 44px;
  text-align: center;
  font-size: 22px;
  color: var(--muted);
}
.status.error { color: #fca5a5; }

(function () {
  "use strict";

  var WEATHER_CODES = {
    0: ["Clear sky", "☀️"],
    1: ["Mainly clear", "🌤️"],
    2: ["Partly cloudy", "⛅"],
    3: ["Overcast", "☁️"],
    45: ["Fog", "🌫️"],
    48: ["Depositing rime fog", "🌫️"],
    51: ["Light drizzle", "🌦️"],
    53: ["Moderate drizzle", "🌦️"],
    55: ["Dense drizzle", "🌦️"],
    56: ["Light freezing drizzle", "🌧️"],
    57: ["Dense freezing drizzle", "🌧️"],
    61: ["Slight rain", "🌧️"],
    63: ["Moderate rain", "🌧️"],
    65: ["Heavy rain", "🌧️"],
    66: ["Light freezing rain", "🌧️"],
    67: ["Heavy freezing rain", "🌧️"],
    71: ["Slight snow fall", "🌨️"],
    73: ["Moderate snow fall", "🌨️"],
    75: ["Heavy snow fall", "❄️"],
    77: ["Snow grains", "🌨️"],
    80: ["Slight rain showers", "🌦️"],
    81: ["Moderate rain showers", "🌧️"],
    82: ["Violent rain showers", "⛈️"],
    85: ["Slight snow showers", "🌨️"],
    86: ["Heavy snow showers", "❄️"],
    95: ["Thunderstorm", "⛈️"],
    96: ["Thunderstorm with slight hail", "⛈️"],
    99: ["Thunderstorm with heavy hail", "⛈️"]
  };

  function qp(name, def) {
    var v = new URLSearchParams(window.location.search).get(name);
    return (v === null || v === "") ? def : v;
  }

  function todayUTC() {
    var d = new Date();
    return d.getUTCFullYear() + "-" +
      String(d.getUTCMonth() + 1).padStart(2, "0") + "-" +
      String(d.getUTCDate()).padStart(2, "0");
  }

  function isValidDate(s) {
    return /^\d{4}-\d{2}-\d{2}$/.test(s) && !isNaN(new Date(s + "T00:00:00Z").getTime());
  }

  function fmtDate(s) {
    var d = new Date(s + "T00:00:00Z");
    return d.toLocaleDateString("en-US", {
      weekday: "long", year: "numeric", month: "long", day: "numeric", timeZone: "UTC"
    });
  }

  function num(v) {
    return (v === null || v === undefined || isNaN(v)) ? "–" : (Math.round(v * 10) / 10);
  }

  function showError(msg) {
    var card = document.getElementById("card");
    card.innerHTML = '<div class="status error"></div>';
    card.querySelector(".status").textContent = msg;
  }

  function esc(s) {
    var d = document.createElement("div");
    d.textContent = s;
    return d.innerHTML;
  }

  var lat = qp("lat", "52.52");
  var lon = qp("lon", "13.405");
  var name = qp("name", "Berlin");
  var date = qp("date", todayUTC());
  if (!isValidDate(date)) { date = todayUTC(); }

  var today = todayUTC();
  var endpoint = (date < today) ? "/api/om/archive" : "/api/om/forecast";

  var params = new URLSearchParams({
    latitude: lat,
    longitude: lon,
    daily: "temperature_2m_max,temperature_2m_min,weather_code",
    hourly: "temperature_2m",
    timezone: "UTC",
    temperature_unit: "celsius",
    start_date: date,
    end_date: date
  });

  var url = endpoint + "?" + params.toString();

  fetch(url, { headers: { "Accept": "application/json" } })
    .then(function (res) {
      if (!res.ok) { throw new Error("Request failed (" + res.status + ")"); }
      return res.json();
    })
    .then(function (data) {
      if (!data || data.error) {
        throw new Error(data && data.reason ? data.reason : "API returned an error");
      }
      render(data);
    })
    .catch(function (err) {
      showError("Weather data could not be loaded. " + (err && err.message ? err.message : ""));
    });

  function render(data) {
    var daily = data.daily || {};
    var hourly = data.hourly || {};

    var maxT, minT, code;
    if (daily.temperature_2m_max && daily.temperature_2m_max.length) {
      maxT = daily.temperature_2m_max[0];
      minT = daily.temperature_2m_min[0];
      code = daily.weather_code ? daily.weather_code[0] : null;
    }

    if (maxT === undefined) {
      showError("Weather data could not be loaded. No data available for this date.");
      return;
    }

    var cond = WEATHER_CODES[code] || ["Unknown", "❓"];

    var times = hourly.time || [];
    var htemps = hourly.temperature_2m || [];
    var hoursHtml = "";
    for (var i = 0; i < times.length; i++) {
      var hh = times[i].slice(11, 16); // HH:MM from ISO
      hoursHtml += '<div class="hour"><div class="h">' + esc(hh) + '</div>' +
        '<div class="t">' + num(htemps[i]) + '°</div></div>';
    }
    if (!hoursHtml) {
      hoursHtml = '<div style="grid-column:1/-1;color:var(--muted)">No hourly data available.</div>';
    }

    var html =
      '<div class="card-head">' +
        '<div>' +
          '<div class="loc-name">' + esc(name) + '</div>' +
          '<div class="loc-sub">' + esc(fmtDate(date)) + '</div>' +
          '<div class="loc-coords">' + esc(lat) + ', ' + esc(lon) + ' · UTC</div>' +
        '</div>' +
        '<div class="cond-box">' +
          '<div class="cond-icon">' + cond[1] + '</div>' +
          '<div class="cond-text">' + esc(cond[0]) + '</div>' +
        '</div>' +
      '</div>' +
      '<div class="body-wrap">' +
        '<div class="temps">' +
          '<div class="temp-tile max"><div class="label">High</div><div class="val">' + num(maxT) + '°C</div></div>' +
          '<div class="temp-tile min"><div class="label">Low</div><div class="val">' + num(minT) + '°C</div></div>' +
        '</div>' +
        '<div class="section-title">Hourly temperature (°C)</div>' +
        '<div class="hours">' + hoursHtml + '</div>' +
      '</div>';

    document.getElementById("card").innerHTML = html;
  }
})();
